    for (int t = 0; t < numTiles; t += UNROLL_FACTOR) {
        // Precompute indices
        int tile_end = min(t + UNROLL_FACTOR, numTiles);

        for (int t_sub = t; t_sub < tile_end; t_sub++) {
            // Load tile from A
