import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel for matrix multiplication with register blocking
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 64
#define BLOCK_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int blockRow = blockIdx.y * TILE_SIZE;
    int blockCol = blockIdx.x * TILE_SIZE;

    int threadRow = threadIdx.y * BLOCK_SIZE;
    int threadCol = threadIdx.x * BLOCK_SIZE;

    float c[BLOCK_SIZE][BLOCK_SIZE] = {0};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A
        int a_col = t * TILE_SIZE + threadIdx.x;
        if (blockRow + threadIdx.y < N && a_col < N) {
            As[threadIdx.y][threadIdx.x] = A[(blockRow + threadIdx.y) * N + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile from B
        int b_row = t * TILE_SIZE + threadIdx.y;
        if (b_row < N && blockCol + threadIdx.x < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + (blockCol + threadIdx.x)];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sums with register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_val = As[threadIdx.y][k];
            float b_val = Bs[k][threadIdx.x];

            for (int i = 0; i < BLOCK_SIZE; i++) {
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    c[i][j] += a_val * b_val;
                }
            }
        }

        __syncthreads();
    }

    // Write results
    for (int i = 0; i < BLOCK_SIZE; i++) {
        for (int j = 0; j < BLOCK_SIZE; j++) {
            int row = blockRow + threadRow + i;
            int col = blockCol + threadCol + j;
            if (row < N && col < N) {
                C[row * N + col] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 threadsPerBlock(TILE_SIZE / BLOCK_SIZE, TILE_SIZE / BLOCK_SIZE);
    dim3 numBlocks((N + TILE_SIZE - 1) / TILE_SIZE, 
                   (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                 B.data_ptr<float>(), 
                                                 C.data_ptr<float>(), 
                                                 N);

    return C;
}
